command -v python3 && python3 - <<'PY'
import re, subprocess, os
pats = {
 'sk-': re.compile(rb'sk-[A-Za-z0-9_\-]{16,}'),
 'ghp_': re.compile(rb'gh[pousr]_[A-Za-z0-9]{20,}'),
 'AKIA': re.compile(rb'AKIA[0-9A-Z]{16}'),
 'AIza': re.compile(rb'AIza[0-9A-Za-z_\-]{30,}'),
 'bearer': re.compile(rb'(?i)bearer\s+[A-Za-z0-9._\-]{20,}'),
}
files = subprocess.run(['git','ls-files','-z'],capture_output=True).stdout.split(b'\0')
files = [f for f in files if f]
hits={}
for f in files:
    p=f
    try:
        data=open(p,'rb').read()
    except Exception as e:
        continue
    for name,rx in pats.items():
        for m in rx.finditer(data):
            line=data.count(b'\n',0,m.start())+1
            tok=m.group(0)
            hits.setdefault((name,os.fsdecode(p),line),0)
            hits[(name,os.fsdecode(p),line)]+=1
for (name,p,line),n in sorted(hits.items()):
    print(f'{name:8} {p}:{line} x{n}')
print('total hit sites:', len(hits))
PY", "description": "Scan tracked files for secret-shaped tokens"}

