import re, subprocess
sk = re.compile(rb'sk-[A-Za-z0-9_\-]{16,}')
def blob(rev, path):
    return subprocess.run(['git','show',f'{rev}:{path}'],capture_output=True).stdout
def files_in(rev):
    out = subprocess.run(['git','ls-tree','-r','--name-only',rev,'--','.dsh/sessions'],capture_output=True).stdout.split(b'\n')
    return [x for x in out if x]
for rev in ['master','origin/master']:
    print(f'===== {rev} =====')
    for p in files_in(rev):
        d = blob(rev, p)
        ms = list(sk.finditer(d))
        if ms:
            for m in ms:
                t=m.group(0)
                print(f'  {p.decode()}  hits={len(ms)}  token={t[:6].decode()}...len={len(t)}')
print()
print('=== which commits added the two leaking files ===')
for f in ['.dsh/sessions/5c7f7229-e0f6-4d50-9e5f-2b7bf773746f/session.v4.jsonl',
          '.dsh/sessions/session-b22e9fec-6fd4-4e7a-8a8b-b8a6595ba3b6/session.v4.jsonl']:
    r = subprocess.run(['git','log','--oneline','--all','--diff-filter=A','--',f],capture_output=True,text=True).stdout.strip()
    print(f, '->', r.replace('\n',' | ') or '(not added in any commit)')
PY", "description": "Check if secret exists in remote branch"}

