import re
sk = re.compile(r'sk-[A-Za-z0-9_\-]{16,}')
def redact(s):
    return sk.sub(lambda m: m.group(0)[:6]+'…<redacted:'+str(len(m.group(0)))+'>', s)
paths = ['.dsh/sessions/5c7f7229-e0f6-4d50-9e5f-2b7bf773746f/session.v4.jsonl',
         '.dsh/sessions/session-b22e9fec-6fd4-4e7a-8a8b-b8a6595ba3b6/session.v4.jsonl']
for p in paths:
    lines = open(p, encoding='utf-8', errors='replace').read().split('\n')
    print('=====', p)
    for i, line in enumerate(lines, 1):
        if sk.search(line):
            for m in sk.finditer(line):
                a=max(0,m.start()-220); b=min(len(line), m.end()+120)
                print(f'  line {i}: ...{redact(line[a:b])}...')
            print()
PY", "description": "Show redacted context around secret occurrences"}

