import re, subprocess, os
def redact(m):
    v=m.group(0)
    return v[:8]+'…REDACTED'
pats = {
 'known-prefix': re.compile(rb'(sk-[A-Za-z0-9_\-]{16,}|gh[pousr]_[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{16}|AIza[0-9A-Za-z_\-]{30,}|xox[baprs]-[A-Za-z0-9\-]{10,})'),
 'assign': re.compile(rb'(?i)((?:api[_-]?key|apikey|secret[_-]?key|access[_-]?token|auth[_-]?token|client[_-]?secret|password|passwd)\s*[:=]\s*)(["\']?)([A-Za-z0-9_\-\.\/\+]{12,})'),
 'bearer': re.compile(rb'(?i)bearer\s+([A-Za-z0-9._\-]{20,})'),
 'jwt': re.compile(rb'eyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}'),
 'privkey': re.compile(rb'-----BEGIN [A-Z ]*PRIVATE KEY-----'),
 'dsn': re.compile(rb'(?i)(postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis)://[^\s:/@]+:([^\s@]{6,})@'),
}
files = subprocess.run(['git','ls-tree','-r','--name-only','-z','2fa3678'],capture_output=True).stdout.split(b'\0')
res={}
for f in [x for x in files if x]:
    p = f.decode('utf-8','replace')
    if not p.startswith('.dsh/sessions'): continue
    d = subprocess.run(['git','show',f'2fa3678:{p}'],capture_output=True).stdout
    for name,rx in pats.items():
        for m in rx.finditer(d):
            line = d.count(b'\n',0,m.start())+1
            val = m.group(0)
            masked = re.sub(rb'[A-Za-z0-9_\-\.\/\+]{12,}', lambda mm: mm.group(0)[:4]+b'…'+str(len(mm.group(0))).encode(), val)[:90]
            res.setdefault((p,name),[]).append((line, masked.decode('utf-8','replace')))
for (p,name),items in sorted(res.items()):
    print(f'{p}  [{name}]  hits={len(items)}')
    for line, s in items[:4]:
        print(f'    L{line}: {s}')
